  'settings.torrents.pex': 'Peer exchange (PEX)',
  'settings.torrents.pexHint': 'Az peerli bir sürünün daha hızlı bulunması için bilinen peerleri zaten bağlı olanlarla değiş tokuş eder.',
  'settings.torrents.privateNote': 'Özel bir torrent, meta verileri bilinir bilinmez, burada ne ayarlanmış olursa olsun her ikisini de otomatik olarak kapatır - yüklenen bir .torrent dosyası için hemen, bir magnet bağlantısı için ise kendi meta verileri sürüden ulaşır ulaşmaz. Çoğu özel tracker, ikisinden birini kullanan hesapları yasaklar.',
  'settings.torrents.engineNote': 'Hedef seed oranı, hedef seed süresi ve port artık bu motorun başlattığı her torrenti gerçekten etkiliyor - port ise yalnızca bu örneğin son yeniden başlatılmasından bu yana ilk torrent için geçerli, çünkü motorun kendi torrent istemcisi yalnızca bir kez oluşturuluyor ve sonrasında bir daha asla yeniden oluşturulmuyor; daha sonra yapılan bir kayıt yine de doğru şekilde saklanıyor ve bir sonraki yeniden başlatmadan itibaren geçerli oluyor. Yükleme sınırı hâlâ yalnızca kaydediliyor ve doğrulanıyor; motorun bunu devam eden bir indirmeye yansıtacak bir yolu henüz yok. Aşağıdaki DHT ve PEX de sıradan (özel olmayan) bir torrent için aynı durumda: bu örneğin kendi varsayılan değeri de devam eden bir indirmeye henüz ulaşmıyor, bu yüzden burada ne ayarlanmış olursa olsun torrent ikisi de açık şekilde seed edilmeye devam ediyor - özel bir torrent ise tamamen farklı bir durum, ayrıntı için aşağıdaki nota bakın. Aşağıdaki yönlendirme düğmesi yine de gerçek bir şey yapar: şu anda bir torrent onu dinliyor olsun ya da olmasın, yukarıda girilen port numarasını dürüstçe yönlendirmesini yönlendiriciden ister.',
