  'onboarding.welcome.title': 'KnightLoader’a hoş geldin',
  'onboarding.welcome.body': 'KnightLoader kendi kendine barındırılan bir indirme yöneticisidir: bir bağlantı yapıştır ya da bırak, onu gerçekten işleyen backend alır - düz dosya bağlantıları için yerleşik motor, medya sayfaları için yt-dlp, zaten ücretini ödediğin hostlar için bir debrid hizmeti, ya da geri kalan her şey için arayüzsüz bir JDownloader. Bu kısa tur, başlamadan önce kontrol etmeye değer tek ayarı kapsıyor.',
  'onboarding.welcome.langLabel': 'Arayüz dili',
  'onboarding.folder.title': 'Dosyalar nereye inmeli?',
  'onboarding.folder.body': 'Bu, tamamlanan indirmelerin yazıldığı klasördür. Bir yol yaz ya da birini seçmek için sunucuya göz at - bunu Genel ayarlar sayfasından istediğin zaman yeniden değiştirebilirsin.',
  'onboarding.accounts.title': 'Ne zaman istersen premium hostlar',
  'onboarding.accounts.body': 'Kuyruk hiçbir hesap olmadan da çalışır. Zaten ücretini ödediğin bir host ya da debrid hizmetinde tam hız istediğinde, girişini Hesaplar altına ekle - burada şimdi ayarlanması gereken bir şey yok.',
  'onboarding.accounts.link': 'Hesapları aç',
  'onboarding.finished.title': 'Hazırsın',
  'onboarding.finished.body': 'Tur burada bitiyor. Ayarlar altındaki Yardım sayfası bu sürümün yaptığı diğer her şeyin tam bir açıklamasını içerir ve çoğu kontrol, bir (i) simgesinin arkasında kendi açıklamasını taşır.',

