  'settings.nav.shortcuts': 'Kısayollar',
  'settings.shortcuts.subtitle': 'Varsayılan klavye kısayoluyla gelen tüm komutlar, uygulandıkları yere göre gruplandırılmış. Bir atamayı değiştir, ya da varsayılana sıfırla.',
  'settings.shortcuts.empty': 'Henüz hiçbir komutun varsayılan kısayolu yok.',
  'settings.shortcuts.change': 'Değiştir',
  'settings.shortcuts.reset': 'Sıfırla',
  'settings.shortcuts.resetAll': 'Tümünü varsayılana sıfırla',
  'settings.shortcuts.resetAllConfirmTitle': 'Tüm kısayollar sıfırlansın mı?',
  'settings.shortcuts.resetAllConfirmBody': 'Yeniden atanan her kısayol kendi varsayılanına döner. Bu geri alınamaz.',
  'settings.shortcuts.resetAllConfirm': 'Tümünü sıfırla',
  'settings.shortcuts.captureTitle': '“{name}” için yeni bir kısayola bas',
  'settings.shortcuts.captureHint': 'Bir tuş kombinasyonuna bas, ya da iptal etmek için Escape.',
