  'settings.headerProfiles.title': 'Header profilleri',
  'settings.headerProfiles.hint': 'Bazı siteler bir dosyayı yalnızca oturum açmış bir tarayıcıya verir, ya da yalnızca çağrı kendi sayfalarından birinden geliyorsa. Bir profil, tam olarak tek bir sitenin headerlarını saklar, hesap anahtarlarınla aynı şekilde şifreli; KnightLoader da o siteden yapılan her indirmede onları birlikte gönderir.',
