  'detail.retriesHint': 'Bu indirmenin bir hatadan sonra kaç kez yeniden denendiği. İndirme biter bitmez sayaç sıfıra döner; yani biten bir satır, dört denemede bitmiş olsa bile sıfır gösterir. Kaç deneme kaldığı burada yazmaz: üst sınır nedene ve hostere bağlıdır, bu sayfa da onu hesaplayamaz.',
  'detail.stallRestarts': 'Durduktan sonraki yeniden başlatmalar',
  'detail.stallRestartsHint': 'Duran indirme nöbetçisinin bu indirmeyi kendiliğinden kaç kez yeniden başlattığı. Yukarıdaki sayaç gibi, indirme biter bitmez sıfıra döner.',
