  'detail.filtered': 'Bağlantı süzgeci tarafından tutuluyor',
  'detail.gaveUp': 'Yeniden denenmeyecek',
  'detail.gaveUpHint': 'Burada bilerek durdu, denemeler bittiği için değil: bir captcha, dolu bir disk ya da bu hoster için “asla” diyen bir kural. Deneme sayısını yükseltmek burada hiçbir şeyi değiştirmez. İşaretin kendisi veritabanına yazılmaz, yani yeniden başlatmadan sonra kaybolur; nedeni ise yerinde durur.',
  'detail.rules': 'Bunu biçimlendiren kurallar',
  'detail.rulesHint': 'Bu bağlantı hazırlanırken üzerinde çalışan kurallar, çalıştıkları sırayla. Görevde adlarıyla saklanırlar: o zamandan beri adı değişmiş bir kural artık bulunamaz, adı hiç olmamış bir kural da o anki konumuyla saklanır. Birine tıklamak onu kural düzenleyicide açar.',
