  'disk.title': 'Hedef klasörler',
  'disk.hint': 'Bir indirmenin inebileceği her klasördeki boş ve dolu alan, bir de kuyruğun oraya daha yazacağı miktar. Değerler, disk sınırlarının da denetlendiği aynı çağrıdan gelir ve en fazla birkaç saniyeliktir. Boş ile dolu her zaman diskin boyutunu vermez: bir dosya sistemi bir dilimi sistem için ayırır ve kullanıcı başına bir kota, bu örneğe diskte gerçekten kalandan azını bırakabilir. Aynı diskteki iki klasör aynı diski gösterir, o yüzden satırları asla toplama.',
  'disk.free': 'Boş',
  'disk.used': 'Dolu',
  'disk.size': 'Disk boyutu',
  'disk.queued': 'Daha yazılacak',
  'disk.queuedHint': 'Hâlâ borçlu olunan indirmelerin bu klasöre ekleyeceği miktar: hosterin bildirdiği boyut, eksi çoktan gelmiş olan. Hosterin boyutunu söylemediği bir indirme burada sıfır sayılır; yani bu bir alt sınırdır, asla bir söz değil, ve bir sürü indirmenin yanında bir klasörün sıfır bayt göstermesinin nedeni de budur. Kapattığın indirmeler dışarıda kalır, listenin altındaki sayaçların izlediği kuralın aynısı. Çalışmakta olan bir indirme, yerini genellikle başladığı anda diskte ayırtmıştır; yani baytları yanındaki boş alan değerinden zaten düşülmüştür, onun üstüne eklenmez.',
  'disk.tasks': '{n} indirme',
  'disk.unknown': 'Bu sistem boş alan bildirmiyor',
  'disk.unknownHint': 'Her çekirdeğe bir diskte ne kadar yer kaldığı sorulamaz ve bu yapının, üzerinde çalıştığı çekirdek için böyle bir çağrısı yok. Yanıtın alınamadığı yerde hiçbir şey tutulmaz: indirmeler, disk sınırları hiç yokken olduğu gibi başlar. Bu satır, onu gerçekten dolmuş bir diskten ayırt edebilesin diye burada.',
  'disk.missing': 'Henüz oluşturulmadı',
  'disk.missingHint': 'Bu klasörü, içine ilk dosyayı yazan oluşturur; yani henüz yok. Değerler, onun üstündeki en yakın var olan klasörü, yani {path} klasörünü anlatır; o da indirmenin ineceği diskin üzerinde durur.',
  'disk.measured': '{path} üzerinde ölçüldü',
  'disk.elsewhereHint': 'Klasörün kendisi ölçülemedi, bu yüzden üstündeki en yakın ölçülebilen klasör ölçüldü. Bir bağlama noktası açılmadıysa bu, indirmenin gitmesi gereken diskten büsbütün başka bir disk olabilir. Sayılardan bir sonuç çıkarmadan önce yola bak.',
  'disk.sampled': '{n} saniye önce okundu',
  'disk.tight': 'Kuyruk sığmıyor',
  'disk.tightHint': 'Bu klasöre, diskte boş olandan fazlası borçlu. Bu satır kendi başına hiçbir şeyi durdurmaz: indirmeler sırası geldikçe tek tek tutulur, hem de İndirmeler ayar sayfasındaki sayılara göre; boyutunu kimsenin bilmediği bir indirme de burada hiç sayılmaz.',
  'disk.truncated': 'Her klasör listede değil',
  'disk.truncatedHint': 'Kuyruk, ayarladıklarının dışında, her okumada ölçülmeye değmeyecek kadar çok klasörü hedefliyor; bu yüzden en az borçlu olanlar dışarıda bırakıldı. Ayarladığın her klasör her zaman burada.',
  'disk.markLow': 'Bunun altında yeni bir şey başlamaz',
  'disk.markStop': 'Bunun altında her şey durur',
  'disk.limits': 'Disk sınırlarını ayarla',
  'disk.stripLabel': 'Hedef klasörlerdeki alan',
  'disk.role.downloads': 'İndirme klasörü',
  'disk.role.category': 'Kategori klasörü',
  'disk.role.work': 'Çalışma klasörü',
  'disk.role.task': 'İndirmenin kendisinde ayarlı',

  'settings.volume.title': 'Hacim kotası',
  'settings.volume.titleHint': 'Bu örneğin indirmeyi bitirdiği miktar, dönem başına senin koyduğun kotaya karşı sayılır. Sayılan, hosterin biten indirme için bildirdiği boyuttur; yani boyutu bildirilmeden biten her şey sıfır sayılır, bir torrentin yüklediği ise hiç sayılmaz. Bu, indirmelerinin bir okumasıdır, hattının bir ölçümü değil: yönlendiricinin gerçekte taşıdığı baytları burada kimse göremez.',
  'settings.volume.cap': 'Dönem başına kota (GB)',
  'settings.volume.capHint': '0, kota yok demektir: sayaç çalışmayı sürdürür ve hiçbir zaman hiçbir şey tutulmaz. Gigabaytlar burada onluk sayılır, bir sağlayıcının hacmini bildirdiği gibi: 500 GB, 465 GiB değil 500 000 000 000 bayttır. Bu sayfanın yukarısındaki disk eşikleri ise ikilik GiB’dir, başka bir soru için başka bir birim.',
  'settings.volume.resetDay': 'Sayacın yeniden başladığı gün',
  'settings.volume.resetDayHint': 'Ayın, sayacın sıfıra döndüğü günü; genellikle hacminin yenilendiği gün. Seçtiğin günden kısa bir ayda bunun yerine o ayın son gününde yeniden başlar ve asla bir sonrakine kaymaz. Tarayıcının değil sunucunun saatine göre sayılır, çünkü kuyruğu tutan sunucudur.',
  'settings.volume.action': 'Kotaya ulaşıldığında',
  'settings.volume.actionHint': 'Hangi yanıtı seçersen seç, çalışmakta olan bir aktarım asla kesilmez: dosyanın ortasında durmak, çoktan harcadığın baytları çöpe atar. “Yalnızca haber ver” hiçbir şeyi değiştirmez, o zaman sayaç tek başına bütün özelliktir. “Artık indirme başlatma” çalışanı bitirir ve sayaç yeniden başlayana kadar kuyruğu tutar; bekleyen her satır da bunu yazar. “Her şeyi yavaşlat” kuyruğu aşağıdaki hızla çalıştırmayı sürdürür.',
  'settings.volume.actionReport': 'Yalnızca haber ver',
  'settings.volume.actionPause': 'Artık indirme başlatma',
  'settings.volume.actionThrottle': 'Her şeyi yavaşlat',
  'settings.volume.throttle': 'Kotadan sonraki hız (KiB/s)',
  'settings.volume.throttleHint': 'Dönemin geri kalanında geçerli olan sınır. Diğer sınırlarının yanında bir tavandır, asla onların yerine geçmez: daha azını isteyen bir gece penceresi ya da sessiz anahtarı yine kazanır. Buradaki 0 hiç sınır yok demek olurdu, o da kota olmamasıyla aynı şeydir; en küçük işe yarar sayı 1.',
  'settings.volume.noCap': 'Kota yok',
  'settings.volume.used': 'Bu dönemde indirilen',
  'settings.volume.usedOf': '{cap} içinden {used}',
  'settings.volume.resetsOn': '{date} tarihinde yeniden başlar',
  'settings.volume.reached': 'Kotaya ulaşıldı.',

  'volume.title': 'İndirilen hacim',
  'volume.titleHint': 'Biten indirmelerin, indirme geçmişinden güne ve aya göre toplanmış hâli. Geçmişin kendi üst sınırı var ve elle boşaltılabilir; sonundan düşmüş aylar bu yüzden burada yok. Yeniden başlattığın bir indirme bir kez sayılır, en son bittiği gün. Takvim sunucununkidir, {zone} olarak.',
