  'failure.botCheck.line': 'Site, videoyu vermeden önce oturum açmış bir oturum istiyor.',
  'failure.botCheck.hint': 'Beklemek, daha yavaş indirmek ya da başka bir tarayıcı kimliği burada hiçbir şeyi değiştirmez. Yalnızca gerçekten oturum açmış olduğun bir tarayıcıdan gelen çerezler değiştirir. Sitenin cookies.txt dosyasını o tarayıcıdan dışa aktar ve buraya yapıştır: dosya şifreli kimlik deposunda saklanır, yt-dlp’ye yalnızca bu sunucunun okuyabildiği bir dosya olarak verilir ve indirme biter bitmez yeniden silinir.',
