  'settings.health.parts': 'Bileşenler',
  'settings.health.partsHint': 'Uygulamanın kendi başına arızalanabilen her bileşeni için bir satır. Bu örnekte hiç kurmadığın bir bileşen, arıza sayılmak yerine bunu söyler; bu yapının soramadığı bir bileşen de aynı şekilde söyler, ki o üçüncü bir yanıttır, sessiz bir sıfır değil. Bir satırı okumak hiçbir şeyi değiştirmez: çalışmadığını söyleyen bir bileşen bir süredir arızalıdır, burada yalnızca bunu öğrenirsin.',
