  'settings.diagnostics.systemTitle': 'Sistem bilgileri',
  'settings.diagnostics.fileTitle': 'Günlük dosyası',
  'settings.diagnostics.fileOn': 'Günlüğü bir dosyaya yaz',
  'settings.diagnostics.fileOnHint': 'Sen açana kadar kapalıdır ve bir güncelleme senin yerine açmaz. Açıkken bu örnek, günlüğe düşen her satırı veri klasöründeki bir dosyaya yazar, böylece önceki geceden kalma bir çökme bir yeniden başlatmadan sonra da okunabilir olur. Bir günlük satırı, abone olduğun bir feedin adresini anabilir, o yüzden dosyayı kendine ait say. Konteynerde aynı satırlar zaten docker logs içine düşer; dosya, oradan akıp gitmiş olanın geride kalan hâlidir.',
  'settings.diagnostics.fileSize': 'Dosya başına boyut',
  'settings.diagnostics.fileSizeHint': 'Dosya bu boyuta ulaşınca adı değiştirilir ve yenisi açılır.',
  'settings.diagnostics.fileKeep': 'Saklanan eski dosya',
