  'settings.diagnostics.fileWhere': 'Nereye yazıldığı',
  'settings.diagnostics.fileWhereHint': 'Sabittir, böylece bir yoldaki yazım hatası günlüğün yazılmasını engelleyemez. Başka bir diske koymak için uygulamayı başlatmadan önce KL_LOG_DIR ayarla.',
