  'settings.diagnostics.fileProblemHint': '{path} yolunun var olduğuna ve bu sürecin altında çalıştığı hesabın oraya yazabildiğine bak. Unraid üzerinde bu genelde klasörün root kullanıcısına ait olduğu, konteynerin ise başka bir kullanıcı olarak çalıştığı anlamına gelir. Bunun dışında hiçbir şey durmadı: son {n} satır bellekte duruyor ve tanılama paketine girmeyi sürdürüyor.',
