  'settings.diagnostics.logSourceHint': 'Bir satırın uygulamanın hangi bölümünden geldiği, satırın kendi başından okunur. Hiçbir bölüm anmayan satırlar “Kalan satırlar” altındadır. Süzülecek bir ağırlık düzeyi yok: bu uygulamada hiçbir satır bir düzey tutmaz.',
