  'settings.owner.identityTitle': 'Bu örneğin kim olarak yazdığı',
  'settings.owner.identityHint': 'Bu örneğin oluşturduğu her dosya bu sahibi ve bu izinleri alır, başlattığı her şey de öyle: yt-dlp, ffmpeg ve birlikte gelen JDownloader. Konteynerde kimlik, konteynerin başladığı anda hangi hesapla başlatıldıysa ona göre sabitlenir ve bu sayfadan hiçbir şey onu değiştiremez.',
