  'settings.owner.envHow': 'Başka bir hesapla çalıştırmak istiyorsan onu başlatma komutunda belirt: --user <uid>:<gid>. Unraid üzerinde bu Extra Parameters alanına girer ve geçerli olması için konteynerin yeniden oluşturulması gerekir.',
  'settings.owner.desktopNote': 'Masaüstü uygulaması senin kendi hesabınla çalışır. PUID, PGID ve UMASK konteyner ayarlarıdır ve burada bir işe yaramazlar.',
  'settings.owner.noOwners': 'Bu sistemde dosyaların sahibi olmaz, yani karşılaştırılacak bir şey yok. Bu bir arıza değil.',
  'settings.owner.checkTitle': 'Klasör denetimi',
  'settings.owner.checkHint': 'Burada her klasöre gerçekten bir dosya ve bir alt klasör yazılır, sonra ikisinin kime ait olduğuna ve başka kimin okuyabildiğine bakılır, ardından ikisi de yeniden kaldırılır. Bunun hesaplanması değil ölçülmesi gerekir: bir paylaşım kendi izin kurallarını getirebilir, set-group-id işaretli bir klasör de bu sürecin sahip olduğundan başka bir grup verir. Denetim, değiştirdiğin bir klasörü kaydettikten sonra kendiliğinden çalışır, bir de düğmeye her bastığında.',
