  'settings.owner.v.ok': 'Dosyalar buraya {fileOwner} olarak ve {fileMode} izinleriyle iner, yeni alt klasörler {subdirMode} izinleriyle, klasörün kendisi de {dirOwner} sahipliğinde. Bunda dikkat çeken bir şey yok.',
  'settings.owner.v.ownerMismatch': 'Dosyalar buraya {fileOwner} olarak iner, ama klasör {dirOwner} sahipliğinde. Okumak genelde yine işler; başka bir hesaptan yeniden adlandırmak, taşımak ve silmek işlemez, klasörün kendi içeriğine sahip olmasını bekleyen her şey de bu dosyaları yabancı sayar.',
  'settings.owner.v.groupUnreadable': 'Dosyalar buraya {fileMode} izinleriyle iner, yani onları yalnızca {fileOwner} açabilir. Başka bir hesapla çalışan her şey adları görür, başka bir şey görmez.',
  'settings.owner.v.dirUnreadable': 'Yeni alt klasörler buraya {subdirMode} izinleriyle iner. İçlerindeki dosyalar ne izin verirse versin, oraya {fileOwner} dışında kimse giremez, her indirme de böyle bir klasöre iner.',
  'settings.owner.v.notWritable': 'Bu örnek buraya hiç yazamıyor: {detail}',
